classDiagram(name = "BankingModel") {
    val customer = classOf(name = "Customer") {
        attribute(name = "accounts", type = "Account", isReadOnly = true)
    }

    val account = classOf(name = "Account") {
        isAbstract = true
        attribute(name = "iban", type = "String", isReadOnly = true)
        attribute(name = "balance", type = "Double", isReadOnly = true)
        attribute(name = "transactions", type = "Transaction", isReadOnly = true)
        operation(name = "getBalance") { returns(typeName = "Double") }
    }

    val checking = classOf(name = "CheckingAccount") {
        extends(general = account)
        attribute(name = "overdraftLimit", type = "Double")
    }

    val savings = classOf(name = "SavingsAccount") {
        extends(general = account)
        attribute(name = "interestRate", type = "Double")
        implements(interface = interestContract)
    }

    val interestContract = interfaceOf(name = "InterestContract") {
        operation(name = "calculateInterest") { returns(typeName = "Double") }
    }

    val transaction = classOf(name = "Transaction") {
        attribute(name = "amount", type = "Double")
        attribute(name = "timestamp", type = "String")
        attribute(name = "type", type = "String")
    }

    association(source = customer, target = account) {
        aggregation = AggregationKind.COMPOSITE
        source { multiplicity(spec = "1") }
        target { multiplicity(spec = "0..*"); role = "accounts" }
    }

    association(source = account, target = transaction) {
        aggregation = AggregationKind.COMPOSITE
        source { multiplicity(spec = "1") }
        target { multiplicity(spec = "0..*"); role = "transactions" }
    }
}

