abstract class NotificationContract {
    + void notify()
}

enum Status {
    ACTIVE
    PASSIVE
    RESIGNED
}

enum ApplicationStatus {
    RECEIVED
    REVIEWED
    ACCEPTED
    REJECTED
}

class StateChapter {
    + name: String
}

class DistrictChapter {
    + name: String
    + processApplication(MembershipApplication)
}

class Member {
    + status: Status
    + contact: NotificationContract
}

class MembershipApplication {
    + status: ApplicationStatus
    + submitDate: Date
    + decisionDate: Date
}

class Committee {
    + name: String
}

class Mandate {
    + term: String
}

class Campaign {
    + name: String
    + startDate: Date
    + endDate: Date
}

class Deployment {
    + hours: Integer
}

abstract class Payment {
    + amount: Double
    + date: Date
}

class MembershipFee extends Payment {
    + contributionYear: Integer
}

class Donation extends Payment {
    + earmarkedFor: Campaign
}

StateChapter "1" *-- "0..*" DistrictChapter : contains
DistrictChapter "1" *-- "0..*" Member : belongsTo
DistrictChapter "0..*" -- "0..*" MembershipApplication : processes
MembershipApplication "0..*" -- "1" Member : emergesFrom
Member "1" -- "1" NotificationContract : has
Committee "0..*" -- "1" Mandate : awards
Mandate "1" -- "1" Member : assignedTo
DistrictChapter "1" *-- "0..*" Campaign : runs
Campaign "0..*" -- "0..*" Deployment : includes
Deployment "1" -- "1" Member : participatesIn
Payment "1" -- "1" Member : from
Donation "0..1" -- "0..*" Campaign : earmarkedFor
MembershipFee "1" -- "0..*" Member : paidBy

