sequenceDiagram(name = "LoginSequence") {
    val loginInterface = lifeline(name = "Login Interface") { isActor = true }
    val authService = lifeline(name = "Authentication Service")
    val userDatabase = lifeline(name = "User Database")
    val user = lifeline(name = "User") { isActor = true }

    message(from = loginInterface, to = authService, label = "submitCredentials()")
    message(from = authService, to = userDatabase, label = "loadUser()")
    message(from = authService, to = authService, label = "verify password")
    reply(from = authService, to = loginInterface, label = "accessToken")
    message(from = loginInterface, to = user, label = "success")
}

sequenceDiagram(name = "CheckoutProcess") {
    val customer = lifeline(name = "Customer") { isActor = true }
    val shop = lifeline(name = "Shop")
    val checkoutService = lifeline(name = "CheckoutService")
    val paymentGateway = lifeline(name = "PaymentGateway")
    val database = lifeline(name = "Database")

    message(from = customer, to = shop, label = "checkout()")
    message(from = shop, to = checkoutService, label = "initiateCheckout()")
    message(from = checkoutService, to = paymentGateway, label = "verifyPaymentDetails()")
    reply(from = paymentGateway, to = checkoutService, label = "paymentValid")

    opt("paymentValid") {
        message(from = checkoutService, to = database, label = "saveOrder()")
        reply(from = database, to = checkoutService)
        message(from = checkoutService, to = paymentGateway, label = "processPayment()")
        reply(from = paymentGateway, to = checkoutService)
        message(from = shop, to = customer, label = "displaySuccess()")
    }

    opt("!paymentValid") {
        message(from = checkoutService, to = shop, label = "displayError()")
    }
}

sequenceDiagram(name = "OrderProcessing") {
    val customer = lifeline(name = "Customer") { isActor = true }
    val orderService = lifeline(name = "OrderService")
    val orchestrator = lifeline(name = "SagaOrchestrator")
    val warehouse = lifeline(name = "WarehouseService")
    val payment = lifeline(name = "PaymentService")
    val shipment = lifeline(name = "ShipmentService")

    message(from = customer, to = orderService, label = "placeOrder()")
    message(from = orderService, to = orchestrator, label = "createOrchestrator()")
    message(from = orchestrator, to = warehouse, label = "reserveItems()")
    reply(from = warehouse, to = orchestrator, label = "itemsReserved")
    message(from = orchestrator, to = payment, label = "executePayment()")
    reply(from = payment, to = orchestrator, label = "paymentProcessed")
    message(from = orchestrator, to = shipment, label = "commissionShipment()")
    reply(from = shipment, to = orchestrator, label = "shipmentCommissioned")
    message(from = orchestrator, to = orderService, label = "completeTransaction()")
    message(from = orderService, to = customer, label = "informOrderStatus()")
    message(from = orchestrator, to = orchestrator, label = "tearDownOrchestrator()")

    alt "Failure Scenarios" {
        message(from = warehouse, to = orchestrator, label = "itemsNotAvailable"); 
        message(from = orchestrator, to = orderService, label = "abortTransaction()");
        message(from = orderService, to = customer, label = "informOrderStatus()");

        message(from = payment, to = orchestrator, label = "paymentFailed"); 
        message(from = orchestrator, to = warehouse, label = "cancelReservation()");
        message(from = warehouse, to = orchestrator, label = "reservationCancelled");
        message(from = orchestrator, to = orderService, label = "abortTransaction()");
        message(from = orderService, to = customer, label = "informOrderStatus()");
    }
}

sequenceDiagram(name = "VehicleSafetySystem") {
    val camera = lifeline(name = "Camera") { isActor = true }
    val radar = lifeline(name = "Radar") { isActor = true }
    val fusionUnit = lifeline(name = "Fusion Unit")
    val emergencyBraking = lifeline(name = "Emergency Braking Assistant")
    val controlUnit = lifeline(name = "Control Unit")
    val diagnosticLog = lifeline(name = "Diagnostic Log")
    val driver = lifeline(name = "Driver") { isActor = true }

    message(from = camera, to = fusionUnit, label = "measurement data")
    message(from = radar, to = fusionUnit, label = "measurement data")
    message(from = fusionUnit, to = emergencyBraking, label = "collision risk (time-to-collision)")

    alt Time-to-collision < threshold
        message(from = emergencyBraking, to = driver, label = "acoustic warning")
        message(from = emergencyBraking, to = controlUnit, label = "initiate autonomous braking")
        loop {
            message(from = controlUnit, to = emergencyBraking, label = "adjust brake pressure")
        }
        message(from = emergencyBraking, to = diagnosticLog, label = "record event")
    else
        message(from = emergencyBraking, to = driver, label = "distance warning")
        message(from = emergencyBraking, to = diagnosticLog, label = "log observed risk")
    end
}

