    }
    val linController = partDef(name = "LIN Controller") {
        generalization(communicationController.id)
    }
    val ethernetController = partDef(name = "Ethernet Controller") {
        generalization(communicationController.id)
    }

    val microcontroller = partDef(name = "Microcontroller") {
        part(name = "cpu", typeId = cpuCore.id)
        part(name = "ram", typeId = ram.id)
        part(name = "flash", typeId = flashMemory.id)
        part(name = "canCtrl", typeId = canController.id)
        part(name = "linCtrl", typeId = linController.id)
        part(name = "ethCtrl", typeId = ethernetController.id)
    }

    // BSW Layer
    val bswModule = partDef(name = "BSW Module", isAbstract = true)
    val mcal = partDef(name = "MCAL") {
        generalization(bswModule.id)
    }
    val canStack = partDef(name = "CAN Stack") {
        generalization(bswModule.id)
    }
    val ethernetStack = partDef(name = "Ethernet Stack") {
        generalization(bswModule.id)
    }
    val os = partDef(name = "OS") {
        generalization(bswModule.id)
    }
    val watchdog = partDef(name = "Watchdog") {
        generalization(bswModule.id)
    }

    val bswLayer = partDef(name = "BSW Layer") {
        part(name = "mcal", typeId = mcal.id)
        part(name = "canStack", typeId = canStack.id)
        part(name = "ethernetStack", typeId = ethernetStack.id)
        part(name = "os", typeId = os.id)
        part(name = "watchdog", typeId = watchdog.id)
    }

    // Application Layer
    val vfb = partDef(name = "Virtual Functional Bus")
    val applicationComponent = partDef(name = "Application Component", isAbstract = true)
    val appComponent1 = partDef(name = "Application Component 1", superType = applicationComponent.id) {
        part(name = "vfb", typeId = vfb.id)
    }
    val appComponent2 = partDef(name = "Application Component 2", superType = applicationComponent.id) {
        part(name = "vfb", typeId = vfb.id)
    }

    val applicationLayer = partDef(name = "Application Layer") {
        part(name = "app1", typeId = appComponent1.id)
        part(name = "app2", typeId = appComponent2.id)
    }

    // BDD
    bdd(name = "ECU BDD") {
        include(microcontroller)
        include(bswLayer)
        include(applicationLayer)
        include(vfb)
        include(applicationComponent)
        include(appComponent1)
        include(appComponent2)
    }
}

