  CAN Stack <|-- BSW Module
  Ethernet Stack <|-- BSW Module
  OS <|-- BSW Module
  Watchdog <|-- BSW Module
  Application Component 1 <|-- Application Component
  Application Component 2 <|-- Application Component
  Application Component 3 <|-- Application Component

import dev.kuml.sysml2.dsl.sysml2Model

sysml2Model(name = "EarthObservationSatellite") {
    val payloadInstrument = partDef(name = "PayloadInstrument", isAbstract = true)

    val payload = partDef(name = "Payload") {
        part(name = "OpticalCamera", typeId = payloadInstrument.id)
        part(name = "SARRadar", typeId = payloadInstrument.id)
    }

    val structureThermal = partDef(name = "StructureAndThermalControl") {
        part(name = "PrimaryStructure")
        part(name = "SolarPanels")
        part(name = "HeatShield")
    }

    val electricalPower = partDef(name = "ElectricalPowerSupply") {
        part(name = "BatteryArray")
        part(name = "SolarPowerRegulator")
        part(name = "PDU")
    }

    val aocs = partDef(name = "AOCS") {
        part(name = "StarSensor")
        part(name = "ReactionWheels")
        part(name = "Thrusters")
    }

    val ttC = partDef(name = "TT&C") {
        part(name = "OnBoardComputer")
        part(name = "RFTransmitter")
        part(name = "RFReceiver")
    }

    bdd(name = "EarthObservationSatellite BDD") {
        include(payload)
        include(structureThermal)
        include(electricalPower)
        include(aocs)
        include(ttC)
    }
}
